if(loadError)return <main className="fatal"><h1>Unable to open local data</h1><p>{loadError}</p><p>Your existing database has not been replaced. Try reopening in the same browser.</p></main>;
if(!state)return <main className="loading"><Activity/><p>Opening your everyday.</p></main>;
const s=state,daily=s.days[date]||emptyDay(),week=weekDates(date),day=parseDate(date).getDay(),today=dateKey(),habits=activeHabits(s,date),percent=consistency(s,[date]),weekPercent=consistency(s,week),template=s.templates[day]||[],session=s.sessions.find(x=>x.id===sessionId),completed=s.sessions.filter(x=>x.completed),weekSessions=completed.filter(x=>week.includes(x.date)),weekElapsed=Math.floor((parseDate(date).getTime()-parseDate(s.settings.start).getTime())/604800000),planWeek=Math.min(12,Math.max(1,weekElapsed+1));
