function exportData(){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`recomp-os-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Backup exported, including photos')}
async function importData(file?:File){if(!file)return;try{const parsed=validateBackup(JSON.parse(await file.text()));setPendingImport(parsed);setModal('import')}catch(e){notify(e instanceof Error?e.message:'Could not read backup')}if(fileRef.current)fileRef.current.value=''}
function startWorkout(){let existing=s.sessions.find(x=>x.date===date&&!x.completed);if(!existing){existing=createSession(s,date);const created=existing;update(s=>s.sessions.push(created))}setSessionId(existing.id);notify('Workout ready. Log each set as you go.')}
function finishWorkout(){if(!session)return;if(!window.confirm('Finish this workout? Only checked sets count toward strength history.'))return;const id=session.id;update(s=>{const x=s.sessions.find(x=>x.id===id)!;x.completed=new Date().toISOString();s.days[x.date]??=emptyDay();s.days[x.date].overrides.workout=true;if(x.cardio.distance>0||x.cardio.duration>0)s.days[x.date].overrides.cardio=true});setModal('summary');notify('Session complete. Another step forward.');}
