const weightEntries=s.metrics.filter(m=>m.kind==='Weight'&&m.unit===s.settings.weightUnit).sort((a,b)=>a.date.localeCompare(b.date)),currentWeight=weightEntries.at(-1)?.value,baseline=weightEntries[0]?.value;
const filtered=s.exercises.filter(e=>e.name.toLowerCase().includes(query.toLowerCase())&&(filter==='All muscles'||e.muscle===filter)).sort((a,b)=>sort==='weight'?b.weight*(b.unit==='kg'?2.20462:1)-a.weight*(a.unit==='kg'?2.20462:1):sort==='last'?(history(s,b.id).map(h=>h.date).sort().at(-1)||'').localeCompare(history(s,a.id).map(h=>h.date).sort().at(-1)||''):a.name.localeCompare(b.name));
